from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']
print('Validation workbook:', path)
print('Sheet names:', wb.sheetnames)
print('\nRequired formula samples:')
for ref in ['H12','L17','H19','L24','H26','L31','H35','L40','H42','H47','H50','L50']:
    print(ref, ws[ref].value)

targets=[]
for r1,r2 in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            targets.append((r,c))
missing=[]
non_formula=[]
for r,c in targets:
    v=ws.cell(r,c).value
    if v is None:
        missing.append(f'{get_column_letter(c)}{r}')
    elif not (isinstance(v,str) and v.startswith('=')):
        non_formula.append((f'{get_column_letter(c)}{r}', v))
print('\nTarget formula check:')
print('Total target cells:', len(targets))
print('Missing cells:', missing)
print('Non-formula cells:', non_formula)
if missing or non_formula:
    raise SystemExit(1)
print('All target cells contain formulas starting with =')

# Confirm no sheets added and outside target diff is not introduced in used area A1:L50, ignoring workbook metadata.
orig=load_workbook('/root/data/workbook.xlsx', data_only=False)
ows=orig['Task']
target_set=set(targets)
changed_outside=[]
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        if (r,c) in target_set:
            continue
        if ws.cell(r,c).value != ows.cell(r,c).value:
            changed_outside.append((f'{get_column_letter(c)}{r}', ows.cell(r,c).value, ws.cell(r,c).value))
print('Changed outside target ranges:', changed_outside[:20], 'count=', len(changed_outside))
if changed_outside:
    raise SystemExit(2)
